import {DRUM_VOICES} from './plugins.js?v=0.14.0';
import {routeAllowed} from './studio-model.js?v=0.14.0';
export function mountRackSteps(d,pattern){const root=document.querySelector('.channel-rack'),project=d.getProject(),engine=d.getEngine(),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let page=0;const pages=document.createElement('label');pages.className='rack-step-page';pages.innerHTML=`Mesure affichée <select aria-label="Mesure du step sequencer">${Array.from({length:pattern.bars},(_,i)=>`<option value="${i}">${i+1}</option>`).join('')}</select>`;root.querySelector('.rack-toolbar').append(pages);
 function draw(){root.querySelectorAll('.rack-inline-steps').forEach(el=>el.remove());for(const row of root.querySelectorAll('.rack-channel')){const trackId=row.querySelector('[data-rack-open]').dataset.rackOpen,t=project.tracks.find(t=>t.id===trackId),data=pattern.channels[t.id];if(t.type==='drums'){const grid=document.createElement('div');grid.className='rack-inline-steps';grid.innerHTML=Object.entries(DRUM_VOICES).map(([voice,name])=>`<div><button data-rack-hit="${voice}" aria-label="Écouter ${name}">${name}</button>${Array.from({length:16},(_,i)=>{const step=page*16+i,on=data?.pattern?.[voice]?.[step]||0;return `<button data-rack-step="${voice}:${step}" class="${on?'on':''} ${Math.floor(i/4)%2?'beat-alt':''}" aria-label="${esc(t.name)}, ${name}, pas ${step+1}" aria-pressed="${!!on}"></button>`;}).join('')}</div>`).join('');row.append(grid);grid.onclick=async e=>{const b=e.target.closest('[data-rack-step],[data-rack-hit]');if(!b)return;if(b.dataset.rackHit){await engine.preview(b.dataset.rackHit);return;}const [voice,raw]=b.dataset.rackStep.split(':'),step=Number(raw);d.checkpoint();const channel=pattern.channels[t.id]??={pattern:Object.fromEntries(Object.keys(DRUM_VOICES).map(v=>[v,Array(pattern.bars*16).fill(0)]))};channel.pattern[voice][step]=channel.pattern[voice][step]?0:.85;for(const c of t.clips)if(c.patternId===pattern.id){c.pattern=structuredClone(channel.pattern);c.patternSteps=pattern.bars*16;}d.changed(true);if(channel.pattern[voice][step]&&!engine.playing)await engine.preview(voice);draw();};}else{let preview=row.querySelector('.rack-note-preview');if(!preview){preview=document.createElement('button');preview.className='rack-note-preview';preview.dataset.rackOpen=t.id;preview.setAttribute('aria-label','Ouvrir le piano roll de '+t.name);row.insertBefore(preview,row.lastElementChild);}const notes=data?.notes||[],low=Math.min(48,...notes.map(n=>n.midi)),high=Math.max(84,...notes.map(n=>n.midi));preview.innerHTML=`<svg viewBox="0 0 240 34" preserveAspectRatio="none">${notes.map(n=>`<rect x="${n.step/(pattern.bars*16)*240}" y="${30-(n.midi-low)/(high-low||1)*28}" width="${Math.max(1,n.len/(pattern.bars*16)*240)}" height="2"/>`).join('')}</svg>`;}}
 }
 for(const row of root.querySelectorAll('.rack-channel')){const t=project.tracks.find(t=>t.id===row.querySelector('[data-rack-open]').dataset.rackOpen),controls=document.createElement('div');controls.className='rack-mini-controls';controls.innerHTML=`<button class="rack-mute ${t.mute?'off':''}" aria-label="Mute ${esc(t.name)}" aria-pressed="${t.mute}">●</button><label>PAN<input type="range" min="-1" max="1" step=".01" value="${t.pan}" aria-label="Panoramique du canal ${esc(t.name)}"></label><label>VOL<input type="range" min="-48" max="12" step=".5" value="${t.volume}" aria-label="Volume du canal ${esc(t.name)}"></label><select aria-label="Sortie du canal ${esc(t.name)}"><option value="master">MASTER</option>${project.tracks.filter(b=>b.type==='bus'&&routeAllowed(project.tracks,t.id,b.id)).map(b=>`<option value="${b.id}" ${t.output===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select>`;row.prepend(controls);controls.querySelector('button').onclick=e=>{d.checkpoint();t.mute=!t.mute;e.currentTarget.setAttribute('aria-pressed',t.mute);e.currentTarget.classList.toggle('off',t.mute);d.changed(true);};for(const input of controls.querySelectorAll('input')){input.onpointerdown=()=>d.checkpoint();input.oninput=()=>{t[input.min==='-1'?'pan':'volume']=Number(input.value);d.changed();};}controls.querySelector('select').onchange=e=>{if(!routeAllowed(project.tracks,t.id,e.target.value))return;d.checkpoint();t.output=e.target.value;d.changed(true);};}
 pages.querySelector('select').onchange=e=>{page=Number(e.target.value);draw();};draw();
}
